const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  var point = ee.Geometry.Point([-79.887682, -2.306934]);
  var region = point.buffer(1000); // 1km radius
  var targetDate = '2024-08-29';
  var startDate = ee.Date(targetDate).advance(-1, 'month');
  var endDate = ee.Date(targetDate).advance(1, 'month');

  // 2. Data Acquisition - Landsat 8 SR
  var collection = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
    .filterBounds(region)
    .filterDate(startDate, endDate)
    .sort('CLOUD_COVER');

  var imgCount = collection.size().getInfo();
  if (imgCount === 0) {
    // Try Landsat 9 as fallback
    collection = ee.ImageCollection('LANDSAT/LC09/C02/T1_L2')
      .filterBounds(region)
      .filterDate(startDate, endDate)
      .sort('CLOUD_COVER');
    imgCount = collection.size().getInfo();
  }

  console.log('Images found:', imgCount);
  if (imgCount === 0) {
    console.log('<answer>C1</answer>');
    return;
  }

  // Get least cloudy image
  var image = ee.Image(collection.first());
  var imageDate = ee.Date(image.get('system:time_start')).format('YYYY-MM-dd').getInfo();
  console.log('Using image from:', imageDate);

  // 3. Cloud Masking
  function maskL8sr(image) {
    var qa = image.select('QA_PIXEL');
    var cloudMask = qa.bitwiseAnd(1 << 3).eq(0); // Cloud bit
    var shadowMask = qa.bitwiseAnd(1 << 4).eq(0); // Shadow bit
    var waterMask = qa.bitwiseAnd(1 << 7).eq(0); // Water bit (keep water)
    return image.updateMask(cloudMask).updateMask(shadowMask).updateMask(waterMask);
  }

  var masked = maskL8sr(image);

  // 4. Calculate NDVI for vegetation detection
  // Bands: B4=Red, B5=NIR (for Landsat 8/9 SR)
  var ndvi = masked.normalizedDifference(['SR_B5', 'SR_B4']).rename('NDVI');

  // Calculate MNDWI for water detection (shrimp ponds)
  // Bands: B3=Green, B6=SWIR1
  var mndwi = masked.normalizedDifference(['SR_B3', 'SR_B6']).rename('MNDWI');

  // 5. Classify pixels
  // Mangrove: High NDVI (>0.6), low MNDWI (<0.3)
  // Shrimp farm: Low NDVI (<0.3), high MNDWI (>0)
  var mangrove = ndvi.gt(0.6).and(mndwi.lt(0.3));
  var shrimp = ndvi.lt(0.3).and(mndwi.gt(0));

  // 6. Count valid pixels
  var pixelStats = ee.Image.cat([mangrove.rename('mangrove'), shrimp.rename('shrimp')])
    .reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: region,
      scale: 30,
      maxPixels: 1e9
    });

  var mangroveCount = pixelStats.get('mangrove').getInfo();
  var shrimpCount = pixelStats.get('shrimp').getInfo();

  console.log('Mangrove pixels:', mangroveCount);
  console.log('Shrimp farm pixels:', shrimpCount);

  // 7. Validation
  if (mangroveCount === 0 && shrimpCount === 0) {
    console.log('<answer>C2</answer>');
    return;
  }

  if (mangroveCount === null || shrimpCount === null) {
    console.log('<answer>C3</answer>');
    return;
  }

  // 8. Determine predominant land use
  var shrimpRatio = shrimpCount / (mangroveCount + shrimpCount);
  console.log('Shrimp ratio:', shrimpRatio.toFixed(3));

  if (shrimpRatio > 0.5) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
